const endpoint = $('Entrada da Rota Clockify').first().json || {};
const e = $input.first().json || {};

return [{
  json: {
    status: 'error',
    stage: 'api',
    source_flow: 'clockify',
    system: endpoint.system || 'clockify',
    url: endpoint.url,
    table: endpoint.table,
    id_field: endpoint.id_field,
    primary_key: endpoint.primary_key || endpoint.id_field,
    error: {
      message: e.message || e.error || 'Falha ao consultar API Clockify',
      details: e
    }
  }
}];

const endpoint = $('Entrada da Rota Clockify').first().json || {};
const pages = $input.all();

function asList(value) {
  if (Array.isArray(value)) return value;
  if (value && typeof value === 'object') {
    if (Array.isArray(value.data)) return value.data;
    if (Array.isArray(value.value)) return value.value;
    return [value];
  }
  return [];
}

function toStr(v) {
  if (v === null || v === undefined) return null;
  return String(v);
}

function transformUsers(users) {
  return users.map((user) => {
    const settings = user.settings || {};
    return {
      id: toStr(user.id) || '',
      email: user.email ?? null,
      name: user.name ?? null,
      profile_picture: user.profilePicture ?? null,
      active_workspace: user.activeWorkspace ?? null,
      default_workspace: user.defaultWorkspace ?? null,
      status: user.status ?? null,
      week_start: settings.weekStart ?? null,
      time_zone: settings.timeZone ?? null,
      time_format: settings.timeFormat ?? null,
      date_format: settings.dateFormat ?? null,
      send_newsletter: settings.sendNewsletter ?? null,
      weekly_updates: settings.weeklyUpdates ?? null,
      long_running: settings.longRunning ?? null,
      scheduled_reports: settings.scheduledReports ?? null,
      approval: settings.approval ?? null,
      pto: settings.pto ?? null,
      alerts: settings.alerts ?? null,
      reminders: settings.reminders ?? null,
      time_tracking_manual: settings.timeTrackingManual ?? null,
      is_compact_view_on: settings.isCompactViewOn ?? null,
      dashboard_selection: settings.dashboardSelection ?? null,
      dashboard_view_type: settings.dashboardViewType ?? null,
      dashboard_pin_to_top: settings.dashboardPinToTop ?? null,
      project_list_collapse: settings.projectListCollapse ?? null,
      collapse_all_project_lists: settings.collapseAllProjectLists ?? null,
      group_similar_entries_disabled: settings.groupSimilarEntriesDisabled ?? null,
      my_start_of_day: settings.myStartOfDay ?? null,
      project_picker_task_filter: settings.projectPickerTaskFilter ?? null,
      lang: settings.lang ?? null,
      multi_factor_enabled: settings.multiFactorEnabled ?? null,
      theme: settings.theme ?? null,
      scheduling: settings.scheduling ?? null,
      onboarding: settings.onboarding ?? null,
      invoice_reminders: settings.invoiceReminders ?? null,
      show_only_working_days: settings.showOnlyWorkingDays ?? null,
      memberships: user.memberships ?? null,
      summary_report_settings: settings.summaryReportSettings ?? null,
      custom_fields: user.customFields ?? null
    };
  });
}

function transformProjects(projects) {
  return projects.map((project) => {
    const hourlyRate = project.hourlyRate || {};
    const costRate = project.costRate || {};
    const estimate = project.estimate || {};
    const timeEstimate = project.timeEstimate || {};
    const budgetEstimate = project.budgetEstimate || {};

    return {
      id: toStr(project.id) || '',
      name: project.name ?? null,
      client_id: project.clientId ?? null,
      workspace_id: project.workspaceId ?? null,
      billable: project.billable ?? null,
      archived: project.archived ?? null,
      color: project.color ?? null,
      duration: project.duration ?? null,
      client_name: project.clientName ?? null,
      note: project.note ?? null,
      public: project.public ?? null,
      template: project.template ?? null,
      hourly_amount: hourlyRate.amount ?? null,
      hourly_currency: hourlyRate.currency ?? null,
      cost_amount: costRate.amount ?? null,
      cost_currency: costRate.currency ?? null,
      estimate_value: estimate.estimate ?? null,
      estimate_type: estimate.type ?? null,
      time_est_estimate: timeEstimate.estimate ?? null,
      time_est_type: timeEstimate.type ?? null,
      time_est_reset_option: timeEstimate.resetOption ?? null,
      time_est_active: timeEstimate.active ?? null,
      time_est_include_non_billable: timeEstimate.includeNonBillable ?? null,
      budget_est_estimate: budgetEstimate.estimate ?? null,
      budget_est_type: budgetEstimate.type ?? null,
      budget_est_reset_option: budgetEstimate.resetOption ?? null,
      budget_est_active: budgetEstimate.active ?? null,
      memberships: project.memberships ?? null
    };
  });
}

function transformClients(clients) {
  return clients.map((client) => ({
    id: toStr(client.id) || '',
    name: client.name ?? null,
    email: client.email ?? null,
    cc_emails: client.ccEmails ?? null,
    workspace_id: client.workspaceId ?? null,
    archived: client.archived ?? null,
    address: client.address ?? null,
    note: client.note ?? null,
    currency_id: client.currencyId ?? null,
    currency_code: client.currencyCode ?? null
  }));
}

function transformTags(tags) {
  return tags.map((tag) => ({
    id: toStr(tag.id) || '',
    name: tag.name ?? null,
    workspace_id: tag.workspaceId ?? null,
    archived: tag.archived ?? null
  }));
}

function normalizeByEndpoint(rows, url) {
  const u = String(url || '').toLowerCase();
  if (u === 'users') return transformUsers(rows);
  if (u === 'projects') return transformProjects(rows);
  if (u === 'clients') return transformClients(rows);
  if (u === 'tags') return transformTags(rows);

  return rows.map((item) => {
    if (item && typeof item === 'object') {
      return { ...item, id: toStr(item.id) || '' };
    }
    return { id: toStr(item) || '', value: item };
  });
}

const rows = pages.flatMap((item) => asList(item.json));
if (rows.length === 0) {
  return [{
    json: {
      status: 'success',
      source_flow: 'clockify',
      system: endpoint.system || 'clockify',
      url: endpoint.url,
      table: endpoint.table,
      id_field: endpoint.id_field,
      primary_key: endpoint.primary_key || endpoint.id_field,
      processed_rows: 0,
      message: 'API retornou sem registros'
    }
  }];
}

const normalized = normalizeByEndpoint(rows, endpoint.url);
return normalized.map((r) => ({ json: { record: r } }));

const endpoint = $('Entrada da Rota Clockify').first().json || {};
const table = endpoint.table;
const idField = endpoint.id_field;

function toSql(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'number') return String(v);
  if (typeof v === 'boolean') return v ? 'true' : 'false';

  const s = (typeof v === 'object') ? JSON.stringify(v) : String(v);
  const q = String.fromCharCode(39);
  return q + s.split(q).join(q + q).split('$').join('$ ') + q;
}

const records = $input
  .all()
  .map((item) => item.json?.record)
  .filter((r) => r && typeof r === 'object' && !Array.isArray(r));

if (!table || !idField || records.length === 0) {
  return [{ json: { upsert_query: 'SELECT 0::int AS affected_rows;' } }];
}

const fieldSet = new Set();
for (const rec of records) {
  for (const key of Object.keys(rec)) {
    if (!key.startsWith('_') && !key.startsWith('$')) fieldSet.add(key);
  }
}

const fields = Array.from(fieldSet);
if (!fields.includes(idField)) fields.unshift(idField);

if (fields.length === 0) {
  return [{ json: { upsert_query: 'SELECT 0::int AS affected_rows;' } }];
}

const columns = fields.join(', ');
const updateFields = fields.filter((f) => f !== idField);
const updates = (updateFields.length > 0)
  ? updateFields.map((f) => `${f}=EXCLUDED.${f}`).join(', ')
  : `${idField}=EXCLUDED.${idField}`;

const valuesList = records
  .map((rec) => `(${fields.map((f) => toSql(rec[f])).join(', ')})`)
  .join(', ');

const upsertQuery = `WITH upserted AS (INSERT INTO raw_data.${table} (${columns}) VALUES ${valuesList} ON CONFLICT (${idField}) DO UPDATE SET ${updates} RETURNING 1) SELECT COUNT(*)::int AS affected_rows FROM upserted;`;
return [{ json: { upsert_query: upsertQuery } }];

const rows = Array.isArray($json.rows) ? $json.rows : [];
const endpoint = $('Entrada da Rota Clockify').first().json || {};
const processedRows = rows.reduce((acc, r) => acc + Number(r.affected_rows || 0), 0);

return [{
  json: {
    status: 'success',
    source_flow: 'clockify',
    system: endpoint.system || 'clockify',
    url: endpoint.url,
    table: endpoint.table,
    id_field: endpoint.id_field,
    primary_key: endpoint.primary_key || endpoint.id_field,
    processed_rows: processedRows,
    message: 'UPSERT concluido com sucesso'
  }
}];

const errors = Array.isArray($json.errors) ? $json.errors : [];
const first = errors[0] || {};
const endpoint = $('Entrada da Rota Clockify').first().json || {};

return [{
  json: {
    status: 'error',
    stage: 'database',
    source_flow: 'clockify',
    system: endpoint.system || 'clockify',
    url: endpoint.url,
    table: endpoint.table,
    id_field: endpoint.id_field,
    primary_key: endpoint.primary_key || endpoint.id_field,
    error: {
      message: first.message || first.error || 'Falha no UPSERT Clockify',
      total_errors: errors.length,
      sample: first
    }
  }
}];
